// src/panels/ViewsMenu.tsx — toolbar control for saving / restoring named views.
//
// A "view" = the current arrangement + visibility (positions, collapsed, hidden).
// Saved views live in localStorage per composite (see viewStore). One view can
// be the DEFAULT, applied automatically when the composite opens. Views can also
// be shared as a compressed URL (?view=) or exported to a JSON file that a
// README can link to via ?viewUrl=.

import { useCallback, useEffect, useRef, useState } from 'react';
import {
  listViews, getDefaultName, getView, saveView, deleteView, setDefault,
  normalizeView, type View,
} from '../viewStore';

export default function ViewsMenu(props: {
  compositeId: string | null;
  captureCurrentView: () => View;
  applyView: (view: View) => void;
}) {
  const { compositeId, captureCurrentView, applyView } = props;
  const [open, setOpen] = useState(false);
  const [, force] = useState(0);          // bump to re-read localStorage after CRUD
  const [toast, setToast] = useState<string | null>(null);
  const fileRef = useRef<HTMLInputElement | null>(null);
  const wrapRef = useRef<HTMLDivElement | null>(null);
  const refresh = () => force((n) => n + 1);

  // Close on outside click.
  useEffect(() => {
    if (!open) return;
    const onDoc = (e: MouseEvent) => {
      if (wrapRef.current && !wrapRef.current.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener('mousedown', onDoc);
    return () => document.removeEventListener('mousedown', onDoc);
  }, [open]);

  const flash = (msg: string) => {
    setToast(msg);
    window.setTimeout(() => setToast(null), 1800);
  };

  const names = compositeId ? listViews(compositeId) : [];
  const defaultName = compositeId ? getDefaultName(compositeId) : null;

  // Mirror the default view to the WORKSPACE (server) so it survives across
  // browsers AND is applied by headless figure renders — localStorage alone is
  // invisible to the renderer. `null` clears the stored default.
  const persistServerDefault = useCallback((view: View | null) => {
    if (!compositeId) return;
    try {
      fetch('/api/composite-default-view', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id: compositeId, view }),
      }).catch(() => { /* offline / static — localStorage still holds it */ });
    } catch { /* no fetch */ }
  }, [compositeId]);

  const onApply = (name: string) => {
    if (!compositeId) return;
    const v = getView(compositeId, name);
    if (v) { applyView(v); setOpen(false); flash(`Applied "${name}"`); }
  };

  const onDelete = (name: string) => {
    if (!compositeId) return;
    deleteView(compositeId, name);
    refresh();
  };

  const onSetDefault = (name: string) => {
    if (!compositeId) return;
    const unset = name === defaultName;
    setDefault(compositeId, unset ? null : name);
    // Keep the workspace default in sync: store the named view, or clear it.
    persistServerDefault(unset ? null : (getView(compositeId, name) ?? null));
    refresh();
  };

  const onExportFile = useCallback(() => {
    const blob = new Blob([JSON.stringify(captureCurrentView(), null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${(compositeId || 'composite').replace(/[^\w.-]+/g, '_')}.view.json`;
    // Firefox only fires the download if the anchor is in the document; and the
    // object URL must outlive the click, so revoke on a timer (a synchronous
    // revoke can cancel the download before it starts).
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 2000);
    setOpen(false);
    flash('View saved to file');
  }, [captureCurrentView, compositeId]);

  // Save the current arrangement as THE default (a reserved "Default" view that
  // opens automatically and that "Go to default" restores).
  const onSaveDefault = useCallback(() => {
    if (!compositeId) return;
    const view = captureCurrentView();
    saveView(compositeId, 'Default', view);
    setDefault(compositeId, 'Default');
    persistServerDefault(view);   // → workspace, so headless renders use it too
    refresh();
    flash('Saved as default');
  }, [compositeId, captureCurrentView, persistServerDefault]);

  const onGoToDefault = () => {
    if (!compositeId || !defaultName) return;
    const v = getView(compositeId, defaultName);
    if (v) { applyView(v); setOpen(false); flash('Default view'); }
  };

  const onLoadFile = (file: File) => {
    const reader = new FileReader();
    reader.onload = () => {
      try {
        // A hand-edited or foreign file is arbitrary JSON. Coerce it the same
        // way every other entry point does (?view=, ?viewUrl=, localStorage all
        // go through normalizeView) so applyView only ever sees a well-formed
        // View — junk positions/collapsed/hidden are dropped instead of being
        // written into the layout store.
        const v = normalizeView(JSON.parse(String(reader.result))) as View;
        applyView(v);
        flash(`Loaded ${file.name}`);
      } catch {
        flash('Invalid view file');
      }
    };
    reader.readAsText(file);
    setOpen(false);
  };

  const itemBtn: React.CSSProperties = {
    display: 'block', width: '100%', textAlign: 'left', padding: '6px 12px',
    fontSize: 12, border: 0, background: '#fff', cursor: 'pointer', color: '#374151',
  };
  const hover = {
    onMouseEnter: (e: React.MouseEvent<HTMLElement>) => (e.currentTarget.style.background = '#f3f4f6'),
    onMouseLeave: (e: React.MouseEvent<HTMLElement>) => (e.currentTarget.style.background = '#fff'),
  };

  return (
    <div ref={wrapRef} style={{ position: 'relative' }}>
      <button
        onClick={() => setOpen((v) => !v)}
        title="Save / restore named views (arrangement + visibility)"
        style={{
          height: 28, padding: '0 10px', fontSize: 12, background: '#fff',
          display: 'inline-flex', alignItems: 'center',
          border: '1px solid #d1d5db', borderRadius: 4, cursor: 'pointer', color: '#374151',
        }}
      >
        Views
      </button>

      {open && (
        <div style={{
          position: 'absolute', top: '100%', right: 0, marginTop: 4,
          background: '#fff', border: '1px solid #d1d5db', borderRadius: 4,
          boxShadow: '0 2px 10px rgba(0,0,0,0.14)', overflow: 'hidden',
          minWidth: 230, zIndex: 20,
        }}>
          {/* Saved views */}
          {names.length === 0 && (
            <div style={{ padding: '8px 12px', fontSize: 12, color: '#9ca3af' }}>
              No saved views yet.
            </div>
          )}
          {names.map((n) => (
            <div key={n} style={{
              display: 'flex', alignItems: 'center', gap: 4,
              borderBottom: '1px solid #f3f4f6',
            }}>
              <button
                onClick={() => onApply(n)}
                style={{ ...itemBtn, flex: 1, paddingRight: 4 }}
                {...hover}
                title={`Apply view "${n}"`}
              >
                {n}
              </button>
              <button
                onClick={() => onSetDefault(n)}
                title={n === defaultName ? 'Default view (opens on load) — click to unset' : 'Set as default (opens on load)'}
                style={{
                  border: 0, background: 'transparent', cursor: 'pointer',
                  fontSize: 13, padding: '0 2px',
                  color: n === defaultName ? '#f59e0b' : '#d1d5db',
                }}
              >
                {n === defaultName ? '★' : '☆'}
              </button>
              <button
                onClick={() => onDelete(n)}
                title={`Delete view "${n}"`}
                style={{ border: 0, background: 'transparent', cursor: 'pointer', fontSize: 13, padding: '0 8px 0 2px', color: '#9ca3af' }}
              >
                ×
              </button>
            </div>
          ))}

          <div style={{ height: 1, background: '#e5e7eb' }} />
          {defaultName && (
            <button onClick={onGoToDefault} style={{ ...itemBtn, color: '#b45309' }} {...hover}>↺ Go to default</button>
          )}
          <button onClick={onSaveDefault} style={itemBtn} {...hover}>★ Save current as default</button>
          <div style={{ height: 1, background: '#e5e7eb' }} />
          <button onClick={onExportFile} style={itemBtn} {...hover}>⭳ Save current view (file)</button>
          <button onClick={() => fileRef.current?.click()} style={itemBtn} {...hover}>⭱ Load view (file)</button>
          <input
            ref={fileRef} type="file" accept="application/json,.json"
            style={{ display: 'none' }}
            onChange={(e) => { const f = e.target.files?.[0]; if (f) onLoadFile(f); e.currentTarget.value = ''; }}
          />
        </div>
      )}

      {toast && (
        <div style={{
          position: 'absolute', top: '100%', right: 0, marginTop: 4,
          background: '#111827', color: '#fff', fontSize: 11, padding: '4px 8px',
          borderRadius: 4, whiteSpace: 'nowrap', zIndex: 30, pointerEvents: 'none',
        }}>
          {toast}
        </div>
      )}
    </div>
  );
}
