// src/layoutStore.ts — per-composite node-position cache in localStorage.
//
// Goals:
//   1. Manual drags survive page reloads (and tab swaps).
//   2. Collapsing/expanding a store does NOT re-layout already-positioned nodes.
//   3. Only newly-visible nodes need fresh auto-layout positions.
//
// Stored shape, one key per composite id:
//   localStorage["bigraph-loom:layout:<composite-id>"] = JSON {
//     [nodeId]: { x: number, y: number }
//   }
//
// Out of scope: server-side persistence, cross-machine sync, multi-user.

import type { Node } from '@xyflow/react';

// Bumped to :v2 when the auto-layout algorithm changed from ELK-layered to the
// cluster-grid. The old builds auto-SAVED ELK positions under the un-suffixed
// key on every render, so without a namespace change every previously-opened
// composite would keep its stale ELK sprawl (applySavedPositions overrides the
// fresh grid) until the user hit Reset-layout. The version bump makes the new
// algorithm start from a clean slate; genuine manual drags under the new layout
// persist under :v2.
const KEY_PREFIX = 'bigraph-loom:layout:v2:';

// Per-node saved layout: position (x,y) plus optional hand-set size (w,h) from
// the node resizer, so a saved view restores BOTH placement and node sizes.
export type LayoutPositions = Record<string, { x: number; y: number; w?: number; h?: number }>;

function keyFor(compositeId: string | null | undefined, modeId = 'hierarchy'): string | null {
  if (!compositeId) return null;
  // 'hierarchy' (the sole mode) keeps the un-suffixed form within the v2
  // namespace; other modes get a :<modeId> suffix.
  return modeId === 'hierarchy'
    ? KEY_PREFIX + compositeId
    : `${KEY_PREFIX}${compositeId}:${modeId}`;
}

/** Read saved positions for a composite (in one layout mode). Returns {} if none or on parse error. */
export function loadLayout(
  compositeId: string | null | undefined,
  modeId?: string,
): LayoutPositions {
  const k = keyFor(compositeId, modeId);
  if (!k) return {};
  try {
    const raw = window.localStorage.getItem(k);
    if (!raw) return {};
    const parsed = JSON.parse(raw);
    if (!parsed || typeof parsed !== 'object') return {};
    return parsed as LayoutPositions;
  } catch {
    return {};
  }
}

/** Overwrite saved positions for a composite. */
export function saveLayout(
  compositeId: string | null | undefined,
  positions: LayoutPositions,
  modeId?: string,
): void {
  const k = keyFor(compositeId, modeId);
  if (!k) return;
  try {
    window.localStorage.setItem(k, JSON.stringify(positions));
  } catch {
    // Storage quota / disabled cookies: persistence is a nice-to-have, never fail loud.
  }
}

/** Wipe the saved layout for one composite (used by the "Reset layout" button). */
export function clearLayout(compositeId: string | null | undefined, modeId?: string): void {
  const k = keyFor(compositeId, modeId);
  if (!k) return;
  try {
    window.localStorage.removeItem(k);
  } catch { /* see saveLayout */ }
}

/** Extract {id → position} from a node list. Used to snapshot for persistence. */
export function positionsFromNodes(nodes: Node[]): LayoutPositions {
  const out: LayoutPositions = {};
  for (const n of nodes) {
    if (!n.position) continue;
    const entry: { x: number; y: number; w?: number; h?: number } = { x: n.position.x, y: n.position.y };
    // Hand-set node size (from the resizer) lives on data._size — persist it too.
    const s = (n.data as { _size?: { width: number; height: number } } | undefined)?._size;
    if (s && s.width && s.height) { entry.w = s.width; entry.h = s.height; }
    out[n.id] = entry;
  }
  return out;
}

/**
 * Pin nodes whose IDs have a saved position; everything else stays at the
 * caller-supplied (auto-layout) position. Returns a new array — does NOT mutate.
 */
export function applySavedPositions(nodes: Node[], saved: LayoutPositions): Node[] {
  return nodes.map((n) => {
    const p = saved[n.id];
    if (!p) return n;
    const node: Node = { ...n, position: { x: p.x, y: p.y } };
    // Restore hand-set node size onto data._size so the node re-renders at it.
    if (p.w && p.h) {
      node.data = { ...(n.data as object), _size: { width: p.w, height: p.h } };
    }
    return node;
  });
}

/** Tiny debounce; trailing only. Generic on argument tuple. */
export function debounce<A extends unknown[]>(
  fn: (...args: A) => void,
  ms: number,
): (...args: A) => void {
  let t: ReturnType<typeof setTimeout> | null = null;
  return (...args: A) => {
    if (t) clearTimeout(t);
    t = setTimeout(() => {
      t = null;
      fn(...args);
    }, ms);
  };
}
